.stringn "$RTUT会話|$s1$FS$c1ANNA|그럼 「이동 범위」에 대해서\n"
.stringn "설명할게.$K$P이동 범위란, $w2이동이나 공격처럼$w2\n"
.stringn "유닛을 행동시킬 수 있는\n"
.stringn "범위를 말하는 거야.$K$P유닛을 이동시키려면,$w2\n"
.stringn "우선 $w2커서를 써.$K$P커서는$w2\n"
