.stringn "가장 대표적인 지팡이$MC……$MD$w4\n"
.stringn "HP를 회복시키는 「라이브」야.$K$P먼저 $w3상대 유닛 옆으로 이동시키고,$w2\n"
.stringn "유닛 메뉴에서 「지팡이」$w1를 선택해.$K$P그리고 $w3사용할 지팡이, $w2쓸 상대 유닛을\n"
.stringn "차례로 선택하면 돼.$w4\n"
