.stringn "경험치도 얻을 수 있어.$K$P그 값은 「지팡이」의 종류에 따라\n"
.stringn "변할 거야.$K$P그리고 $w2회복계 지팡이는$w2\n"
.stringn "100% 성공하지만$w3\n"
.stringn "공격 보조형 지팡이는 실패하는 경우가 있어.$K$P이 경우 $w2획득하는 경험치는$w2\n"
.stringn "원래의 값보다 줄어드니까\n"
.stringn "조심해.$K"
