.stringn "끝이야.$K$P적장$MC……$MD$w4 보스 유닛만 쓰러뜨리면 되는\n"
.stringn "맵이지만, $w3그만큼$w2\n"
.stringn "갑작스럽게 맵 클리어가 될 때도 있어.$K$P보스 유닛과의 싸움이 다가오면$w2\n"
.stringn "놓친 것이 없나$w2\n"
.stringn "생각하면서 싸워 줘.$K"
db 0
.align 4
//MS_T04敵将の撃破_04

