Text_95B4:
.stringn "$RTUT会話|$s1$FS$c1ANNA|그럼 「특효」에 대해서\n"
.stringn "설명할게.$K$P「특효」란, $w2공격할 때$w2\n"
.stringn "어떤 조건을 만족시킴으로써 $w2평소 이상의\n"
.stringn "대미지를 줄 수 있는 것을 말해.$K$P페가수스 나이트나 드래곤 나이트 같은$w2\n"
.stringn "「비행계 유닛」이 「활」로 공격당하는\n"
.stringn "경우가 그렇지.$K"
db 0
.align 4
