.stringn "무기 아이콘을 봐봐.$w4\n"
.stringn "하얗게 빛나고 있지?$K$P이건 「특효」가\n"
.stringn "발생한다는 의미야.$K$P이렇게 전투 정보 윈도우에서도$w2\n"
.stringn "「특효」의 발생 여부를\n"
.stringn "알 수 있어.$K$P그럼 $w2실제로 싸워 볼게.$K"
